#!/usr/bin/env python3
from __future__ import annotations

import json
import math
import os
import queue
import random
import signal
import subprocess
import sys
import threading
import time
from dataclasses import dataclass, field
from pathlib import Path
from typing import Dict, Iterable, List, Optional, Tuple


HELP_TEXT = """
USAGE: 

   ./executable  [-i <path to directory>] [-s <positive integer>] [-d <a
                 string containing two space-seprated positive integers>]
                 [-n <{1,2,3,4,5,6}>] [-r] [-t] [-o] [-q] [--] [--version]
                 [-h] <Array of strings> ...


Where: 

   -i <path to directory>,  --replaydirectory <path to directory>
     The path to directory for replay output.

   -s <positive integer>,  --seed <positive integer>
     The seed for the map generator.

   -d <a string containing two space-seprated positive integers>, 
      --dimensions <a string containing two space-seprated positive
      integers>
     The dimensions of the map.

   -n <{1,2,3,4,5,6}>,  --nplayers <{1,2,3,4,5,6}>
     Create a map that will accommodate n players [SINGLE PLAYER MODE
     ONLY].

   -r,  --noreplay
     Turns off the replay generation.

   -t,  --timeout
     Causes game environment to ignore timeouts (give all bots infinite
     time).

   -o,  --override
     Overrides player-sent names using cmd args [SERVER ONLY].

   -q,  --quiet
     Runs game in quiet mode, producing machine-parsable output.

   --,  --ignore_rest
     Ignores the rest of the labeled arguments following this flag.

   --version
     Displays version information and exits.

   -h,  --help
     Displays usage information and exits.

   <Array of strings>  (accepted multiple times)
     Start commands for bots.


   Halite Game Environment
""".lstrip("\n")


BRIEF_USAGE = """
Brief USAGE: 

   ./executable  [-i <path to directory>] [-s <positive integer>] [-d <a
                 string containing two space-seprated positive integers>]
                 [-n <{1,2,3,4,5,6}>] [-r] [-t] [-o] [-q] [--] [--version]
                 [-h] <Array of strings> ...
""".lstrip("\n")


VERSION_TEXT = "\n./executable  version: 1.2\n"
GENERIC_NO_BOT = "Please provide the launch command string for at least one bot.\nUse the --help flag for usage details.\n"
INVALID_OVERRIDE = "Invalid number of player parameters with override switch enabled.  Override intended for server use only.\n"
INVALID_PLAYER_COUNT = "\nA map can only accommodate between 1 and 6 players.\n"
REPLAY_DIR_ERROR = "terminate called after throwing an instance of 'std::runtime_error'\n  what():  Could not open file for replay\n"


DIR_STILL = 0
DIR_NORTH = 1
DIR_EAST = 2
DIR_SOUTH = 3
DIR_WEST = 4

DIR_DELTAS = {
    DIR_STILL: (0, 0),
    DIR_NORTH: (0, -1),
    DIR_EAST: (1, 0),
    DIR_SOUTH: (0, 1),
    DIR_WEST: (-1, 0),
}


@dataclass
class Config:
    replay_dir: Optional[Path] = None
    seed: Optional[int] = None
    dimensions: Optional[Tuple[int, int]] = None
    nplayers: Optional[int] = None
    noreplay: bool = False
    ignore_timeouts: bool = False
    override_names: bool = False
    quiet: bool = False
    show_help: bool = False
    show_version: bool = False
    bot_args: List[str] = field(default_factory=list)


@dataclass
class ParseFailure(Exception):
    argument: str
    message: str


@dataclass
class Player:
    player_id: int
    command: str
    override_name: Optional[str] = None
    process: Optional[subprocess.Popen[str]] = None
    stdout_queue: queue.Queue[Optional[str]] = field(default_factory=queue.Queue)
    stderr_lines: List[str] = field(default_factory=list)
    stderr_thread: Optional[threading.Thread] = None
    stdout_thread: Optional[threading.Thread] = None
    name: str = ""
    init_failed: bool = False
    init_failed_before_frame0: bool = False
    single_player_init_failure: bool = False
    alive: bool = True
    last_alive_frame: int = -1
    rank: int = 0
    error_message: Optional[str] = None
    log_path: Optional[Path] = None


def write_stdout(text: str) -> None:
    sys.stdout.write(text)
    sys.stdout.flush()


def write_stderr(text: str) -> None:
    sys.stderr.write(text)
    sys.stderr.flush()


def print_help() -> None:
    write_stdout("\n" + HELP_TEXT)


def print_version() -> None:
    write_stdout(VERSION_TEXT)


def print_parse_error(argument: str, message: str) -> None:
    text = f"PARSE ERROR: Argument: {argument}\n             {message}\n\n{BRIEF_USAGE}\nFor complete USAGE and HELP type: \n\n   ./executable --help\n"
    write_stderr(text)


def parse_args(argv: List[str]) -> Config:
    cfg = Config()
    stop_parsing = False
    i = 0
    while i < len(argv):
        arg = argv[i]
        if stop_parsing:
            cfg.bot_args.append(arg)
            i += 1
            continue
        if arg in ("--", "--ignore_rest"):
            stop_parsing = True
            i += 1
            continue
        if arg in ("-h", "--help"):
            cfg.show_help = True
            i += 1
            continue
        if arg == "--version":
            cfg.show_version = True
            i += 1
            continue
        if arg in ("-i", "--replaydirectory"):
            if i + 1 >= len(argv):
                raise ParseFailure("-i (--replaydirectory)", "Missing a value for this argument!")
            cfg.replay_dir = Path(argv[i + 1])
            i += 2
            continue
        if arg in ("-s", "--seed"):
            if i + 1 >= len(argv):
                raise ParseFailure("-s (--seed)", "Missing a value for this argument!")
            value = argv[i + 1]
            try:
                cfg.seed = int(value, 10)
            except ValueError as exc:
                raise ParseFailure("-s (--seed)", f"Couldn't read argument value from string '{value}'") from exc
            i += 2
            continue
        if arg in ("-d", "--dimensions"):
            if i + 1 >= len(argv):
                raise ParseFailure("-d (--dimensions)", "Missing a value for this argument!")
            value = argv[i + 1]
            parts = value.split()
            if len(parts) != 2:
                raise ParseFailure(
                    "-d (--dimensions)",
                    f"Couldn't read argument value from string '{value}'",
                )
            try:
                cfg.dimensions = (int(parts[0], 10), int(parts[1], 10))
            except ValueError as exc:
                raise ParseFailure(
                    "-d (--dimensions)",
                    f"Couldn't read argument value from string '{value}'",
                ) from exc
            i += 2
            continue
        if arg in ("-n", "--nplayers"):
            if i + 1 >= len(argv):
                raise ParseFailure("-n (--nplayers)", "Missing a value for this argument!")
            value = argv[i + 1]
            try:
                cfg.nplayers = int(value, 10)
            except ValueError as exc:
                raise ParseFailure("-n (--nplayers)", f"Couldn't read argument value from string '{value}'") from exc
            i += 2
            continue
        if arg in ("-r", "--noreplay"):
            cfg.noreplay = True
            i += 1
            continue
        if arg in ("-t", "--timeout"):
            cfg.ignore_timeouts = True
            i += 1
            continue
        if arg in ("-o", "--override"):
            cfg.override_names = True
            i += 1
            continue
        if arg in ("-q", "--quiet"):
            cfg.quiet = True
            i += 1
            continue
        cfg.bot_args.append(arg)
        i += 1
    return cfg


def pick_actual_seed(seed: Optional[int]) -> int:
    if seed is None:
        return random.randint(1, 0xFFFFFFFF)
    wrapped = seed & 0xFFFFFFFF
    if wrapped == 0:
        return random.randint(1, 0xFFFFFFFF)
    return wrapped


def choose_default_dimensions(rng: random.Random, slot_count: int) -> Tuple[int, int]:
    if slot_count <= 1:
        size = rng.choice([20, 25, 30, 35, 40, 45, 50])
        return size, size
    if slot_count in (2, 4):
        size = rng.choice([20, 24, 28, 32, 36, 40, 44, 48])
        return size, size
    size = rng.choice([18, 24, 30, 36, 42, 48])
    return size, size


def adjust_dimensions(width: int, height: int, slot_count: int) -> Tuple[int, int]:
    if slot_count in (2, 4, 5, 6):
        width = max(2, width - (width % 2))
        height = max(2, height - (height % 2))
    if slot_count == 3:
        width = max(3, width - (width % 3))
        height = max(3, height - (height % 3))
    return width, height


def make_run_id() -> int:
    return int(time.time())


def cell_index(x: int, y: int, width: int) -> int:
    return y * width + x


def neighbors(x: int, y: int, width: int, height: int) -> Iterable[Tuple[int, int]]:
    yield ((x + 1) % width, y)
    yield ((x - 1) % width, y)
    yield (x, (y + 1) % height)
    yield (x, (y - 1) % height)


def reflect_horizontally(values: List[List[float]], width: int) -> List[List[float]]:
    out: List[List[float]] = []
    base_width = len(values[0])
    for row in values:
        reflected = row[:]
        while len(reflected) < width:
            mirrored = reflected[-2::-1] if width % 2 == 1 else reflected[::-1]
            for value in mirrored:
                if len(reflected) >= width:
                    break
                reflected.append(value)
        out.append(reflected[:width])
    return out


def reflect_quadrants(values: List[List[float]], width: int, height: int) -> List[List[float]]:
    horiz = reflect_horizontally(values, width)
    out = [row[:] for row in horiz]
    while len(out) < height:
        mirrored_rows = out[-2::-1] if height % 2 == 1 else out[::-1]
        for row in mirrored_rows:
            if len(out) >= height:
                break
            out.append(row[:])
    return out[:height]


def smooth_field(values: List[List[float]], passes: int) -> List[List[float]]:
    height = len(values)
    width = len(values[0])
    current = [row[:] for row in values]
    for _ in range(passes):
        nxt = [[0.0 for _ in range(width)] for _ in range(height)]
        for y in range(height):
            for x in range(width):
                total = current[y][x] * 4.0
                weight = 4.0
                for nx, ny in neighbors(x, y, width, height):
                    total += current[ny][nx] * 2.0
                    weight += 2.0
                for dx in (-1, 1):
                    for dy in (-1, 1):
                        total += current[(y + dy) % height][(x + dx) % width]
                        weight += 1.0
                nxt[y][x] = total / weight
        current = nxt
    return current


def symmetry_mode(slot_count: int) -> str:
    if slot_count in (2, 5, 6):
        return "horizontal"
    if slot_count in (3, 4):
        return "quadrant"
    return "none"


def expand_symmetric_field(rng: random.Random, width: int, height: int, slot_count: int, passes: int) -> List[List[float]]:
    mode = symmetry_mode(slot_count)
    if mode == "none":
        base_width = width
        base_height = height
    elif mode == "horizontal":
        base_width = max(1, (width + 1) // 2)
        base_height = height
    else:
        base_width = max(1, (width + 1) // 2)
        base_height = max(1, (height + 1) // 2)
    base = [[rng.random() for _ in range(base_width)] for _ in range(base_height)]
    base = smooth_field(base, passes)
    if mode == "none":
        return base
    if mode == "horizontal":
        return reflect_horizontally(base, width)
    return reflect_quadrants(base, width, height)


def starting_positions(width: int, height: int, slot_count: int) -> List[Tuple[int, int]]:
    cx = width // 2
    cy = height // 2
    if slot_count <= 1:
        return [(cx, cy)]
    if slot_count == 2:
        return [((cx - 1) % width, cy), (cx % width, cy)]
    if slot_count == 3:
        return [(width // 6, cy), ((width // 2) % width, cy), ((5 * width) // 6 % width, cy)]
    if slot_count == 4:
        return [
            ((cx - 1) % width, (cy - 1) % height),
            (cx % width, (cy - 1) % height),
            ((cx - 1) % width, cy % height),
            (cx % width, cy % height),
        ]
    if slot_count == 5:
        return [
            ((cx - 2) % width, cy),
            ((cx - 1) % width, cy),
            (cx % width, cy),
            ((cx + 1) % width, cy),
            ((cx + 2) % width, cy),
        ]
    return [
        ((cx - 2) % width, (cy - 1) % height),
        ((cx - 1) % width, (cy - 1) % height),
        (cx % width, (cy - 1) % height),
        ((cx - 2) % width, cy % height),
        ((cx - 1) % width, cy % height),
        (cx % width, cy % height),
    ]


def generate_map(
    width: int,
    height: int,
    slot_count: int,
    player_count: int,
    actual_seed: int,
) -> Tuple[List[int], List[int], List[int]]:
    rng = random.Random(actual_seed)
    production_field = expand_symmetric_field(rng, width, height, slot_count, 4)
    strength_field = expand_symmetric_field(rng, width, height, slot_count, 5)

    productions: List[int] = []
    strengths: List[int] = []
    for y in range(height):
        for x in range(width):
            p_value = int(round(production_field[y][x] * 14.0))
            s_value = int(round(20.0 + strength_field[y][x] * 230.0))
            productions.append(max(0, min(15, p_value)))
            strengths.append(max(0, min(255, s_value)))

    owners = [0 for _ in range(width * height)]
    starts = starting_positions(width, height, slot_count)
    for i, (x, y) in enumerate(starts[:slot_count]):
        idx = cell_index(x, y, width)
        strengths[idx] = max(40, min(120, strengths[idx]))
        if i < player_count:
            owners[idx] = i + 1
        else:
            owners[idx] = 0
    return productions, owners, strengths


def encode_state(owners: List[int], strengths: List[int]) -> str:
    rle: List[str] = []
    if owners:
        run_owner = owners[0]
        run_count = 1
        for owner in owners[1:]:
            if owner == run_owner:
                run_count += 1
                continue
            rle.append(str(run_count))
            rle.append(str(run_owner))
            run_owner = owner
            run_count = 1
        rle.append(str(run_count))
        rle.append(str(run_owner))
    return " ".join(rle + [str(value) for value in strengths]) + " \n"


def frame_grid(owners: List[int], strengths: List[int], width: int, height: int) -> List[List[List[int]]]:
    out: List[List[List[int]]] = []
    for y in range(height):
        row: List[List[int]] = []
        for x in range(width):
            idx = cell_index(x, y, width)
            row.append([owners[idx], strengths[idx]])
        out.append(row)
    return out


def blank_moves(width: int, height: int) -> List[List[int]]:
    return [[0 for _ in range(width)] for _ in range(height)]


def count_owned(owners: List[int], player_id: int) -> int:
    return sum(1 for owner in owners if owner == player_id)


def total_strength(owners: List[int], strengths: List[int], player_id: int) -> int:
    return sum(strength for owner, strength in zip(owners, strengths) if owner == player_id)


def parse_moves(line: str, owner_id: int, owners: List[int], width: int, height: int) -> Optional[List[List[int]]]:
    line = line.strip()
    grid = blank_moves(width, height)
    if not line:
        return grid
    parts = line.split()
    if len(parts) % 3 != 0:
        return None
    for i in range(0, len(parts), 3):
        try:
            x = int(parts[i], 10)
