def cell_index(x: int, y: int, width: int) -> int:
    return y * width + x


def neighbors(x: int, y: int, width: int, height: int) -> Iterable[Tuple[int, int]]:
    yield ((x + 1) % width, y)
    yield ((x - 1) % width, y)
    yield (x, (y + 1) % height)
    yield (x, (y - 1) % height)


def reflect_horizontally(values: List[List[float]], width: int) -> List[List[float]]:
    out: List[List[float]] = []
    base_width = len(values[0])
    for row in values:
        reflected = row[:]
        while len(reflected) < width:
            mirrored = reflected[-2::-1] if width % 2 == 1 else reflected[::-1]
            for value in mirrored:
                if len(reflected) >= width:
                    break
                reflected.append(value)
        out.append(reflected[:width])
    return out


def reflect_quadrants(values: List[List[float]], width: int, height: int) -> List[List[float]]:
    horiz = reflect_horizontally(values, width)
    out = [row[:] for row in horiz]
    while len(out) < height:
        mirrored_rows = out[-2::-1] if height % 2 == 1 else out[::-1]
        for row in mirrored_rows:
            if len(out) >= height:
                break
            out.append(row[:])
    return out[:height]


def smooth_field(values: List[List[float]], passes: int) -> List[List[float]]:
    height = len(values)
    width = len(values[0])
    current = [row[:] for row in values]
    for _ in range(passes):
        nxt = [[0.0 for _ in range(width)] for _ in range(height)]
        for y in range(height):
            for x in range(width):
                total = current[y][x] * 4.0
                weight = 4.0
                for nx, ny in neighbors(x, y, width, height):
                    total += current[ny][nx] * 2.0
                    weight += 2.0
                for dx in (-1, 1):
                    for dy in (-1, 1):
                        total += current[(y + dy) % height][(x + dx) % width]
                        weight += 1.0
                nxt[y][x] = total / weight
        current = nxt
    return current


def symmetry_mode(slot_count: int) -> str:
    if slot_count in (2, 5, 6):
        return "horizontal"
    if slot_count in (3, 4):
        return "quadrant"
    return "none"


def expand_symmetric_field(rng: random.Random, width: int, height: int, slot_count: int, passes: int) -> List[List[float]]:
    mode = symmetry_mode(slot_count)
    if mode == "none":
        base_width = width
        base_height = height
    elif mode == "horizontal":
        base_width = max(1, (width + 1) // 2)
        base_height = height
