def make_log_path(player_id: int, run_id: int, cwd: Path) -> Path:
    return cwd / f"{player_id}-{run_id}.log"


def write_player_log(player: Player, run_id: int, cwd: Path, phase: str) -> None:
    if not player.stderr_lines and not player.error_message:
        return
    path = make_log_path(player.player_id, run_id, cwd)
    lines = [f" --- {phase} ---", ""]
    if player.error_message:
        lines.append("ERRORED!")
        lines.append(player.error_message)
    if player.stderr_lines:
        if lines[-1] != "":
            lines.append("")
        lines.extend(player.stderr_lines)
    path.write_text("\n".join(lines).rstrip("\n") + "\n", encoding="utf-8")
    player.log_path = path


def format_path_for_output(path: Path, default_to_dot: bool = False) -> str:
    if path.is_absolute():
        return str(path)
    text = str(path)
    if default_to_dot and not text.startswith("./"):
        return f"./{text}"
    return text


def rank_players(players: List[Player], owners: List[int], strengths: List[int]) -> None:
    scored = []
    for player in players:
        scored.append(
            (
                count_owned(owners, player.player_id),
                total_strength(owners, strengths, player.player_id),
                player.player_id,
                player,
            )
        )
    scored.sort(key=lambda item: (item[0], item[1], item[2]), reverse=True)
    for rank, (_, _, _, player) in enumerate(scored, start=1):
        player.rank = rank


def quiet_footer(players: List[Player]) -> None:
    errored = [player for player in players if player.log_path is not None]
    if not errored:
        write_stdout(" \n")
        return
    for player in errored:
        write_stdout(f"{player.player_id} \n")
        write_stdout(f"{player.log_path.name} \n")


