TIMEOUT = TimeoutSentinel()


@dataclass
class Bot:
    player_id: int
    command: str
    process: subprocess.Popen[str] | None = None
    reader: LineReader | None = None
    name: str = ""
    initialized: bool = False
    init_failed: bool = False
    errored: bool = False
    error_kind: str | None = None
    error_line: str | None = None
    error_log_name: str | None = None
    last_alive_frame: int = -1
    board_removed: bool = False
    frame_logs: list[tuple[int | str, str | None]] | None = None

    def launch(self) -> None:
        self.process = subprocess.Popen(
            ["sh", "-c", self.command],
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            bufsize=1,
        )
        assert self.process.stdout is not None
        self.reader = LineReader(self.process.stdout)
        self.reader.start()
        self.frame_logs = []

    def send(self, line: str) -> None:
        if self.process is None or self.process.stdin is None:
            return
        try:
            self.process.stdin.write(line)
            self.process.stdin.flush()
        except BrokenPipeError:
            pass

    def read_line(self, timeout_seconds: float, ignore_timeouts: bool):
        assert self.reader is not None
        if ignore_timeouts:
            while True:
                try:
                    return self.reader.queue.get(timeout=0.1)
                except queue.Empty:
                    if self.reader.closed and self.reader.queue.empty():
                        return None
            return None
        deadline = time.monotonic() + timeout_seconds
        while True:
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                if self.reader.closed and self.reader.queue.empty():
                    return None
                return TIMEOUT
            try:
                return self.reader.queue.get(timeout=min(remaining, 0.1))
            except queue.Empty:
                if self.reader.closed and self.reader.queue.empty():
                    return None

    def poll(self) -> int | None:
        if self.process is None:
            return None
        return self.process.poll()

    def kill(self) -> None:
        if self.process is None:
            return
        if self.process.poll() is None:
            self.process.kill()
        try:
            self.process.wait(timeout=0.5)
        except subprocess.TimeoutExpired:
            pass


