def random_production(rng: random.Random) -> int:
    return max(0, min(15, int(rng.triangular(0, 15, 3))))


def random_strength(rng: random.Random) -> int:
    return rng.randrange(0, 256)


def generate_map(
    seed: int,
    width: int,
    height: int,
    map_players: int,
    actual_players: int,
) -> tuple[list[int], list[int], list[int]]:
    rng = random.Random(seed)
    size = width * height
    productions = [-1] * size
    strengths = [-1] * size
    owners = [0] * size
    transforms = symmetry_transforms(map_players, width, height)

    for y in range(height):
        for x in range(width):
            idx = y * width + x
            if productions[idx] != -1:
                continue
            orbit = unique_orbit(transforms, x, y)
            production = random_production(rng)
            strength = random_strength(rng)
            for ox, oy in orbit:
                oidx = oy * width + ox
                productions[oidx] = production
                strengths[oidx] = strength

    starts = choose_start_positions(map_players, width, height)
    start_strength = rng.randrange(70, 161)
    start_production = max(1, random_production(rng))
    for player_id, (sx, sy) in enumerate(starts[:actual_players], start=1):
        idx = sy * width + sx
        owners[idx] = player_id
        productions[idx] = start_production
        strengths[idx] = start_strength

    return productions, owners, strengths


def index_to_xy(index: int, width: int) -> tuple[int, int]:
    return index % width, index // width


def neighbor_index(index: int, width: int, height: int, direction: int) -> int:
    x, y = index_to_xy(index, width)
    if direction == 1:
        y = (y - 1) % height
    elif direction == 2:
        x = (x + 1) % width
    elif direction == 3:
        y = (y + 1) % height
    elif direction == 4:
        x = (x - 1) % width
    return y * width + x


def production_matrix(productions: list[int], width: int, height: int) -> list[list[int]]:
    return [productions[y * width : (y + 1) * width] for y in range(height)]


def frame_matrix(owners: list[int], strengths: list[int], width: int, height: int) -> list[list[list[int]]]:
    rows: list[list[list[int]]] = []
    for y in range(height):
        row: list[list[int]] = []
        for x in range(width):
            idx = y * width + x
            row.append([owners[idx], strengths[idx]])
        rows.append(row)
    return rows


def move_matrix(directions: list[int], width: int, height: int) -> list[list[int]]:
    return [directions[y * width : (y + 1) * width] for y in range(height)]


def format_production_line(productions: list[int]) -> str:
    return " ".join(str(value) for value in productions) + " "


def format_state_line(owners: list[int], strengths: list[int]) -> str:
    rle: list[str] = []
    run_owner = owners[0]
    run_count = 1
    for owner in owners[1:]:
        if owner == run_owner:
            run_count += 1
            continue
        rle.append(str(run_count))
        rle.append(str(run_owner))
        run_owner = owner
        run_count = 1
    rle.append(str(run_count))
    rle.append(str(run_owner))
    return " ".join(rle + [str(value) for value in strengths]) + " "


